      <div class="stat-row"><span class="stat-label">Avg Reviews</span><span class="stat-value">{genre_stats['Fiction']['avg_reviews']:,.0f}</span></div>
      <div class="stat-row"><span class="stat-label">Price Range</span><span class="stat-value">${genre_stats['Fiction']['min_price']}–${genre_stats['Fiction']['max_price']}</span></div>
      <div class="stat-row"><span class="stat-label">Rating Range</span><span class="stat-value">{genre_stats['Fiction']['min_rating']:.1f}–{genre_stats['Fiction']['max_rating']:.1f}</span></div>
    </div>
    <div class="genre-card nonfiction">
      <h4 style="color: var(--nonfiction);">Non-Fiction ({nonfiction_count} entries, {nonfiction_count*100/total:.1f}%)</h4>
      <div class="stat-row"><span class="stat-label">Average Price</span><span class="stat-value">${genre_stats['Non Fiction']['avg_price']:.2f}</span></div>
