nf_yearly_ratings = [round(yearly_genre[y].get('Non Fiction', {}).get('avg_rating', 0), 2) for y in years]
fic_yearly_reviews = [round(yearly_genre[y].get('Fiction', {}).get('avg_reviews', 0), 0) for y in years]
nf_yearly_reviews = [round(yearly_genre[y].get('Non Fiction', {}).get('avg_reviews', 0), 0) for y in years]

# Scatter data for chart
scatter_fiction = [(p, r) for p, r, g in scatter_data if g == 'Fiction']
scatter_nonfiction = [(p, r) for p, r, g in scatter_data if g == 'Non Fiction']

# Price segment chart data
seg_labels = [s for s in segment_order if segment_data[s]['count'] > 0]
seg_counts = [segment_data[s]['count'] for s in seg_labels]
seg_avg_ratings = [round(sum(segment_data[s]['ratings'])/len(segment_data[s]['ratings']), 2) for s in seg_labels]

# Yearly genre counts
fic_yearly_counts = [yearly_genre[y].get('Fiction', {}).get('count', 0) for y in years]
nf_yearly_counts = [yearly_genre[y].get('Non Fiction', {}).get('count', 0) for y in years]

# Price changes YoY
price_changes = []
