    background: var(--card-bg);
    border-radius: 10px;
    padding: 32px;
    margin-bottom: 24px;
    box-shadow: 0 1px 6px rgba(0,0,0,0.04);
  }}
  section h2 {{
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 6px;
    padding-bottom: 10px;
    border-bottom: 2px solid var(--border);
  }}
  section h3 {{
    font-size: 1.05rem;
    font-weight: 600;
    color: var(--primary-light);
    margin: 20px 0 10px;
  }}
  p {{ margin: 10px 0; color: var(--text); font-size: 0.95rem; }}
  .chart-container {{
    position: relative;
    margin: 20px 0;
    max-height: 420px;
  }}
  .chart-container canvas {{
    max-height: 400px;
  }}
  .chart-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin: 20px 0;
  }}
  .chart-cell {{
    position: relative;
  }}
  .chart-cell canvas {{
    max-height: 350px;
  }}
  table {{
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0;
    font-size: 0.88rem;
  }}
  th {{
    background: var(--primary);
    color: white;
    padding: 10px 12px;
    text-align: left;
    font-weight: 600;
