    border-bottom: 1px solid var(--border);
  }}
  tr:nth-child(even) td {{ background: #f8fafc; }}
  tr:hover td {{ background: #edf2f7; }}
  .comparison-grid {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin: 16px 0;
