  }}
  .genre-card h4 {{
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 12px;
  }}
  .genre-card .stat-row {{
    display: flex;
    justify-content: space-between;
    padding: 5px 0;
    border-bottom: 1px solid rgba(0,0,0,0.06);
    font-size: 0.9rem;
  }}
  .genre-card .stat-row:last-child {{ border-bottom: none; }}
  .genre-card .stat-label {{ color: var(--text-light); }}
  .genre-card .stat-value {{ font-weight: 600; }}
  .insight-box {{
    background: #fffff0;
    border-left: 4px solid #d69e2e;
    padding: 14px 18px;
    margin: 16px 0;
    border-radius: 0 6px 6px 0;
