  }}
  .insight-box strong {{ color: #975a16; }}
  .rec-list {{
    list-style: none;
    padding: 0;
  }}
  .rec-list li {{
    padding: 14px 18px;
    margin: 10px 0;
    background: #f0fff4;
    border-left: 4px solid var(--success);
    border-radius: 0 6px 6px 0;
    font-size: 0.93rem;
  }}
  .rec-list li strong {{ color: #276749; }}
