print(f"Avg Rating: {avg_rating:.2f}")
print(f"Avg Price: ${avg_price:.2f}")
print(f"Pearson r: {pearson_r:.4f}")
print(f"Fiction: {fiction_count}, Non-Fiction: {nonfiction_count}")

import csv
import math
from collections import defaultdict

# Load data
rows = []
with open('/app/benchmark/data.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append({
            'Name': row['Name'],
            'Author': row['Author'],
            'User Rating': float(row['User Rating']),
            'Reviews': int(row['Reviews']),
            'Price': int(row['Price']),
            'Year': int(row['Year']),
            'Genre': row['Genre']
        })

total = len(rows)

# ---- KPIs ----
avg_rating = sum(r['User Rating'] for r in rows) / total
avg_price = sum(r['Price'] for r in rows) / total
avg_reviews = sum(r['Reviews'] for r in rows) / total

# Pearson correlation (Price vs User Rating)
mean_price = avg_price
mean_rating = avg_rating
num = sum((r['Price'] - mean_price) * (r['User Rating'] - mean_rating) for r in rows)
den_price = math.sqrt(sum((r['Price'] - mean_price)**2 for r in rows))
den_rating = math.sqrt(sum((r['User Rating'] - mean_rating)**2 for r in rows))
pearson_r = num / (den_price * den_rating) if den_price * den_rating != 0 else 0

# Genre split
fiction = [r for r in rows if r['Genre'] == 'Fiction']
nonfiction = [r for r in rows if r['Genre'] == 'Non Fiction']
fiction_count = len(fiction)
nonfiction_count = len(nonfiction)

genre_stats = {}
for label, subset in [('Fiction', fiction), ('Non Fiction', nonfiction)]:
    genre_stats[label] = {
        'count': len(subset),
        'avg_price': sum(r['Price'] for r in subset) / len(subset),
        'avg_rating': sum(r['User Rating'] for r in subset) / len(subset),
        'avg_reviews': sum(r['Reviews'] for r in subset) / len(subset),
        'min_price': min(r['Price'] for r in subset),
        'max_price': max(r['Price'] for r in subset),
        'min_rating': min(r['User Rating'] for r in subset),
        'max_rating': max(r['User Rating'] for r in subset),
    }

# Per-genre Pearson
genre_pearson = {}
for label, subset in [('Fiction', fiction), ('Non Fiction', nonfiction)]:
    mp = sum(r['Price'] for r in subset) / len(subset)
    mr = sum(r['User Rating'] for r in subset) / len(subset)
    n = sum((r['Price'] - mp) * (r['User Rating'] - mr) for r in subset)
    dp = math.sqrt(sum((r['Price'] - mp)**2 for r in subset))
    dr = math.sqrt(sum((r['User Rating'] - mr)**2 for r in subset))
    genre_pearson[label] = n / (dp * dr) if dp * dr != 0 else 0

# Year-over-year trends
years = sorted(set(r['Year'] for r in rows))
yearly = {}
for y in years:
    subset = [r for r in rows if r['Year'] == y]
    yearly[y] = {
        'count': len(subset),
        'avg_price': sum(r['Price'] for r in subset) / len(subset),
        'avg_rating': sum(r['User Rating'] for r in subset) / len(subset),
        'avg_reviews': sum(r['Reviews'] for r in subset) / len(subset),
    }

# Year-over-year by genre
yearly_genre = {}
for y in years:
    yearly_genre[y] = {}
    for label, full_subset in [('Fiction', fiction), ('Non Fiction', nonfiction)]:
        subset = [r for r in full_subset if r['Year'] == y]
        if subset:
            yearly_genre[y][label] = {
                'count': len(subset),
                'avg_price': sum(r['Price'] for r in subset) / len(subset),
                'avg_rating': sum(r['User Rating'] for r in subset) / len(subset),
                'avg_reviews': sum(r['Reviews'] for r in subset) / len(subset),
            }

# Top authors by frequency
author_freq = defaultdict(int)
author_ratings = defaultdict(list)
author_prices = defaultdict(list)
for r in rows:
    author_freq[r['Author']] += 1
    author_ratings[r['Author']].append(r['User Rating'])
    author_prices[r['Author']].append(r['Price'])

top_authors = sorted(author_freq.items(), key=lambda x: -x[1])[:15]

# Price segments
def price_segment(p):
    if p == 0:
        return '$0 (Free)'
    elif p <= 5:
        return '$1–$5'
    elif p <= 10:
        return '$6–$10'
    elif p <= 15:
        return '$11–$15'
    elif p <= 20:
        return '$16–$20'
    elif p <= 30:
        return '$21–$30'
    else:
        return '$31+'

segment_order = ['$0 (Free)', '$1–$5', '$6–$10', '$11–$15', '$16–$20', '$21–$30', '$31+']
segment_data = defaultdict(lambda: {'count': 0, 'ratings': [], 'prices': []})
for r in rows:
    seg = price_segment(r['Price'])
    segment_data[seg]['count'] += 1
    segment_data[seg]['ratings'].append(r['User Rating'])
    segment_data[seg]['prices'].append(r['Price'])

# Scatter data (price, rating) for all rows
scatter_data = [(r['Price'], r['User Rating'], r['Genre']) for r in rows]

# Unique books
unique_books = len(set((r['Name'], r['Author']) for r in rows))

# ---- Build HTML ----

# Prepare chart data as JSON-like strings
yearly_labels = str(years)
yearly_prices = [round(yearly[y]['avg_price'], 2) for y in years]
yearly_ratings = [round(yearly[y]['avg_rating'], 2) for y in years]
yearly_reviews = [round(yearly[y]['avg_reviews'], 0) for y in years]

# Fiction vs Non Fiction yearly
fic_yearly_prices = [round(yearly_genre[y].get('Fiction', {}).get('avg_price', 0), 2) for y in years]
nf_yearly_prices = [round(yearly_genre[y].get('Non Fiction', {}).get('avg_price', 0), 2) for y in years]
fic_yearly_ratings = [round(yearly_genre[y].get('Fiction', {}).get('avg_rating', 0), 2) for y in years]
nf_yearly_ratings = [round(yearly_genre[y].get('Non Fiction', {}).get('avg_rating', 0), 2) for y in years]
fic_yearly_reviews = [round(yearly_genre[y].get('Fiction', {}).get('avg_reviews', 0), 0) for y in years]
nf_yearly_reviews = [round(yearly_genre[y].get('Non Fiction', {}).get('avg_reviews', 0), 0) for y in years]

# Scatter data for chart
scatter_fiction = [(p, r) for p, r, g in scatter_data if g == 'Fiction']
scatter_nonfiction = [(p, r) for p, r, g in scatter_data if g == 'Non Fiction']

# Price segment chart data
seg_labels = [s for s in segment_order if segment_data[s]['count'] > 0]
seg_counts = [segment_data[s]['count'] for s in seg_labels]
seg_avg_ratings = [round(sum(segment_data[s]['ratings'])/len(segment_data[s]['ratings']), 2) for s in seg_labels]

# Yearly genre counts
fic_yearly_counts = [yearly_genre[y].get('Fiction', {}).get('count', 0) for y in years]
nf_yearly_counts = [yearly_genre[y].get('Non Fiction', {}).get('count', 0) for y in years]

# Price changes YoY
price_changes = []
for i in range(1, len(years)):
    change = yearly[years[i]]['avg_price'] - yearly[years[i-1]]['avg_price']
    price_changes.append(round(change, 2))

# Rating changes YoY
rating_changes = []
for i in range(1, len(years)):
    change = yearly[years[i]]['avg_rating'] - yearly[years[i-1]]['avg_rating']
    rating_changes.append(round(change, 3))

# Find inflection points
max_price_year = max(years, key=lambda y: yearly[y]['avg_price'])
min_price_year = min(years, key=lambda y: yearly[y]['avg_price'])
max_rating_year = max(years, key=lambda y: yearly[y]['avg_rating'])
min_rating_year = min(years, key=lambda y: yearly[y]['avg_rating'])

# Biggest YoY price drop/increase
biggest_price_drop_idx = min(range(len(price_changes)), key=lambda i: price_changes[i])
biggest_price_rise_idx = max(range(len(price_changes)), key=lambda i: price_changes[i])

